    {
        Term term;
        Token nextToken = tokenSource.peek();
        switch (nextToken.kind)
        {
        case FUNCTOR:
            term = functor();
            break;
        case LSQPAREN:
            term = listFunctor();
            break;
        case VAR:
            term = variable();
            break;
        case INTEGER_LITERAL:
