        ByteArrayOutputStream byteStream = new ByteArrayOutputStream();
        try {
            byte[] blobChunk = new byte[]{0};
            for (int i = 1; blobChunk.length > 0; i += CHUNK_SIZE) {
                if (i > 1) {
                    byteStream.write(blobChunk);
