        byteBuffer.limit(SIZE_OF_INT).position(0);
        final long filePosition = (index * (long)ENTRY_LENGTH) + ENTRY_TYPE_OFFSET;
        try
        {
            if (SIZE_OF_INT != fileChannel.write(byteBuffer, filePosition))
