private TimeoutExtImpl removeNode(int index)
   {
      TimeoutExtImpl res = queue[index];
      if (index == size)
      {
         --size;
         queue[index] = null;
         return res;
      }
      swap(index, size);  
      --size;
      queue[res.index] = null;
      if (normalizeUp(index))
         return res;  
      long t = queue[index].time;
      int c = index << 1;
      while (c <= size)
      {
         TimeoutExtImpl l = queue[c];
         if (c + 1 <= size)
         {
            TimeoutExtImpl r = queue[c + 1];
            if (l.time <= r.time)
            {
               if (t <= l.time)
                  break;  
               swap(index, c);
               index = c;
            }
            else
            {
               if (t <= r.time)
                  break;  
               swap(index, c + 1);
               index = c + 1;
            }
         }
         else
         {  
            if (t <= l.time)
