		Object credentials = getPreAuthenticatedCredentials(request);
		if (principal == null) {
			if (logger.isDebugEnabled()) {
				logger.debug("No pre-authenticated principal found in request");
			}
			return;
		}
		if (logger.isDebugEnabled()) {
			logger.debug("preAuthenticatedPrincipal = " + principal
