                }
            }
            deploymentUnit = deploymentUnit.getParent();  
        }
        while (deploymentUnit != null);
        for (PersistenceUnitMetadata pu : puHolder.getPersistenceUnits()) {
            pu.setAnnotationIndex(annotationIndexes);    
