                    final Template template = ve.getTemplate(templateName);
                    template.merge(context, writer);
                } finally {
                    writer.close();
                }
                genFile.persist();

            } catch (final IOException ex) {
                throw new GenerateException("Error merging template '" + templateName + "' to '" + filename + "'!", ex);
            }
        }

    }

