      c = missedChar.charValue();
      missedChar = null;
    } else {
      int read = in.read();
      if (read == -1)
        return -1;
      c = (char) read;
      if (c == '\\') {
        read = in.read();
        if (read == -1)
          return -1;
        char c2 = (char) read;
        if (c2 == 'u') {
          final StringBuilder buff = new StringBuilder(8);
          for (int i = 0; i < 4; ++i) {
            read = in.read();
            if (read == -1)
              return -1;
            buff.append((char) read);
          }
          cursor += 6;
          return (char) Integer.parseInt(buff.toString(), 16);
        } else {
          missedChar = c2;
