          final String roleAsString = servers.field(server);
          final ROLES role = roleAsString != null ? ROLES.valueOf(roleAsString.toUpperCase(Locale.ENGLISH)) : defRole;
          if (role != ROLES.MASTER)
            it.remove();
        }
      }
      return masters;
    }
