                int columnType = getType(index);
                if (column.isPrimaryKey() && columnType == FIELD_TYPE_NULL) {
                    valid = false;
                }
                columnTypes[index] = columnType;
                values[index] = getValue(column);
            }
            row = getRow(columnTypes, values);
            if (!valid) {
                invalidPositions.add(getPosition());
                row.setValid(false);
            }
        }
        return row;
